parameters.jsCode:
const userId = $('Postgres - Look Up User').first().json.id;
const userName = $('Postgres - Look Up User').first().json.name;
const userMobile = $('Postgres - Look Up User').first().json.mobile;
const userRole = $('Postgres - Look Up User').first().json.user_type;
const userQuery = $('WhatsApp Trigger').first().json.messages[0].text.body;

const SUPABASE_URL = "https://osszfmwnxnfngtgfmugv.supabase.co";
const SUPABASE_ANON_KEY = "your-supabase-anon-key-here";
const OPENAI_API_KEY = "your-openai-api-key-here";

// 1. Fetch memory history from Supabase
const histResponse = await fetch(`${SUPABASE_URL}/rest/v1/chat_history?user_id=eq.${userId}&order=created_at.asc&limit=10`, {
  headers: {
    'apikey': SUPABASE_ANON_KEY,
    'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
  }
});
const history = histResponse.ok ? await histResponse.json() : [];

// 2. Build messages array
const messages = [
  {
    role: 'system',
    content: `You are the Berger Paints AI Agent assistant for DSEs (District Sales Executives) and DSOs (District Sales Officers). The current user is:\n- Name: ${userName}\n- User ID: ${userId}\n- Mobile: ${userMobile}\n- Role: ${userRole}\n\nUse your tools to query info to answer the user's questions. Always search for leads, sites, check-in history, or estimates matching their queries. Refer to specific lead IDs when executing detail or log searches. Do not hallucinate data.`
  }
];

history.forEach(h => {
  messages.push({ role: h.role, content: h.content });
});
messages.push({ role: 'user', content: userQuery });

// 3. Define Tools
const tools = [
  {
    type: 'function',
    function: {
      name: 'query_lead_details',
      description: 'Query detailed info about leads (including customer name, mobile, address, town, status, budget, assigned painter, assigned retailer). Option filters: lead_id, current_status, town.',
      parameters: {
        type: 'object',
        properties: {
          lead_id: { type: 'string' },
          current_status: { type: 'string' },
          town: { type: 'string' }
        }
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'query_site_visits',
      description: 'Query visit check-in logs and remarks for a lead. Requires lead_id.',
      parameters: {
        type: 'object',
        properties: {
          lead_id: { type: 'string' }
        },
        required: ['lead_id']
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'query_estimates',
      description: 'Query version numbers and breakdowns of estimates for a lead. Requires lead_id.',
      parameters: {
        type: 'object',
        properties: {
          lead_id: { type: 'string' }
        },
        required: ['lead_id']
      }
    }
  }
];

// 4. Request completion to OpenAI
let response = await fetch('https://api.openai.com/v1/chat/completions', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${OPENAI_API_KEY}`
  },
  body: JSON.stringify({ model: 'gpt-4o-mini', messages, tools })
});
let data = await response.json();
let choice = data.choices[0].message;

// 5. Run tool call loop if OpenAI requests tool execution
if (choice.tool_calls && choice.tool_calls.length > 0) {
  messages.push(choice);

  const toolPromises = choice.tool_calls.map(async (toolCall) => {
    const args = JSON.parse(toolCall.function.arguments);
    let queryUrl = '';
    if (toolCall.function.name === 'query_lead_details') {
      queryUrl = `${SUPABASE_URL}/rest/v1/lead_detail_drilldown_view?or=(dse_id.eq.${userId},dso_id.eq.${userId})`;
      if (args.lead_id) queryUrl += `&lead_id=eq.${args.lead_id}`;
      if (args.current_status) queryUrl += `&current_status=eq.${args.current_status}`;
      if (args.town) queryUrl += `&town=ilike.*${args.town}*`;
    } else if (toolCall.function.name === 'query_site_visits') {
      queryUrl = `${SUPABASE_URL}/rest/v1/site_visits?lead_id=eq.${args.lead_id}`;
    } else if (toolCall.function.name === 'query_estimates') {
      queryUrl = `${SUPABASE_URL}/rest/v1/estimate_details_view?lead_id=eq.${args.lead_id}`;
    }

    const toolRes = await fetch(queryUrl, {
      headers: {
        'apikey': SUPABASE_ANON_KEY,
        'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
      }
    });
    const toolData = toolRes.ok ? await toolRes.json() : { error: 'Failed to fetch database records' };
    return {
      role: 'tool',
      tool_call_id: toolCall.id,
      name: toolCall.function.name,
      content: JSON.stringify(toolData)
    };
  });

  const toolOutputs = await Promise.all(toolPromises);
  toolOutputs.forEach(out => messages.push(out));

  // Query OpenAI again with the tool output content
  response = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${OPENAI_API_KEY}`
    },
    body: JSON.stringify({ model: 'gpt-4o-mini', messages })
  });
  data = await response.json();
  choice = data.choices[0].message;
}

const finalAnswer = choice.content || 'I encountered an error retrieving that database record.';

// 6. Save chat history to Supabase
await fetch(`${SUPABASE_URL}/rest/v1/chat_history`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'apikey': SUPABASE_ANON_KEY,
    'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
  },
  body: JSON.stringify([
    { user_id: userId, role: 'user', content: userQuery },
    { user_id: userId, role: 'assistant', content: finalAnswer }
  ])
});

return [{ json: { output: finalAnswer } }];

